`UsageEvent` owns its invariants in `__post_init__`; `parse_event` translates every failure mode into `InvalidEvent` with `raise ... from exc`, so the root cause stays in the traceback. `summarize` loops once, catching only `InvalidEvent`, and in strict mode raises an `ExceptionGroup` after the loop so that no failure hides another. The tests are plain functions.

**`ledger.py`**

```python
from __future__ import annotations

from collections import Counter
from collections.abc import Iterable, Mapping
from dataclasses import dataclass, field


class LedgerError(Exception):
    """Base class for ledger errors."""


class InvalidEvent(LedgerError):
    def __init__(self, index: int, reason: str) -> None:
        super().__init__(f"event {index}: {reason}")
        self.index = index
        self.reason = reason


@dataclass(frozen=True, slots=True, kw_only=True)
class UsageEvent:
    tenant: str
    tokens: int
    model: str = "default"

    def __post_init__(self) -> None:
        if not self.tenant:
            raise ValueError("tenant must not be empty")
        if self.tokens < 0:
            raise ValueError("tokens must be >= 0")


@dataclass(frozen=True, slots=True)
class Summary:
    tokens_by_tenant: dict[str, int] = field(default_factory=dict)
    errors: tuple[InvalidEvent, ...] = ()


def parse_event(raw: Mapping[str, object], index: int = 0) -> UsageEvent:
    try:
        tenant, tokens = raw["tenant"], raw["tokens"]
    except KeyError as exc:
        raise InvalidEvent(index, f"missing field {exc.args[0]!r}") from exc
    model = raw.get("model", "default")
    if not isinstance(tenant, str) or not isinstance(model, str):
        raise InvalidEvent(index, "tenant and model must be strings")
    if type(tokens) is not int:
        raise InvalidEvent(index, "tokens must be an int")
    try:
        return UsageEvent(tenant=tenant, tokens=tokens, model=model)
    except ValueError as exc:
        raise InvalidEvent(index, str(exc)) from exc


def summarize(raw_events: Iterable[Mapping[str, object]], *, strict: bool = False) -> Summary:
    totals: Counter[str] = Counter()
    errors: list[InvalidEvent] = []
    for index, raw in enumerate(raw_events):
        try:
            event = parse_event(raw, index)
        except InvalidEvent as exc:
            errors.append(exc)
            continue
        totals[event.tenant] += event.tokens
    if strict and errors:
        raise ExceptionGroup(f"{len(errors)} invalid events", errors)
    return Summary(dict(totals), tuple(errors))
```

**`test_ledger.py`**

```python
import pytest

from ledger import InvalidEvent, UsageEvent, parse_event, summarize

GOOD = [
    {"tenant": "acme", "tokens": 10},
    {"tenant": "acme", "tokens": 5, "model": "m"},
    {"tenant": "globex", "tokens": 7},
]


def test_aggregates_valid_events():
    s = summarize(GOOD)
    assert s.tokens_by_tenant == {"acme": 15, "globex": 7}
    assert s.errors == ()


def test_collects_errors_without_stopping():
    raw = [
        {"tenant": "a", "tokens": 1},
        {"tokens": 2},
        {"tenant": "a", "tokens": -1},
        {"tenant": "a", "tokens": True},
        {"tenant": "b", "tokens": 4},
    ]
    s = summarize(raw)
    assert s.tokens_by_tenant == {"a": 1, "b": 4}
    assert [e.index for e in s.errors] == [1, 2, 3]


def test_cause_chain_is_preserved():
    with pytest.raises(InvalidEvent) as ei:
        parse_event({"tokens": 1}, 7)
    assert isinstance(ei.value.__cause__, KeyError)
    assert ei.value.index == 7
    with pytest.raises(InvalidEvent) as ei2:
        parse_event({"tenant": "", "tokens": 1})
    assert isinstance(ei2.value.__cause__, ValueError)


def test_strict_raises_exception_group():
    with pytest.raises(ExceptionGroup) as eg:
        summarize([{"tenant": "a"}, {"tenant": "b", "tokens": "x"}], strict=True)
    assert len(eg.value.exceptions) == 2
    assert all(isinstance(e, InvalidEvent) for e in eg.value.exceptions)


def test_strict_ok_when_clean():
    assert summarize(GOOD, strict=True).tokens_by_tenant["acme"] == 15


def test_event_is_frozen_slotted_kw_only():
    e = UsageEvent(tenant="a", tokens=1)
    with pytest.raises(AttributeError):
        e.tokens = 2
    assert not hasattr(e, "__dict__")
    with pytest.raises(TypeError):
        UsageEvent("a", 1)


def test_accepts_generator_input():
    assert summarize(iter(GOOD)).tokens_by_tenant["globex"] == 7
```

Run `pytest -q`, then `mypy --strict ledger.py` if you have it installed.
